using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMemoryCache();
var app = builder.Build();

// Encryption key loaded from mounted volume
var keyPath = Environment.GetEnvironmentVariable("KEY_FILE_PATH") ?? "/etc/secrets/encryption.key";
var ivPath = Environment.GetEnvironmentVariable("IV_FILE_PATH") ?? "/etc/secrets/encryption.iv";

byte[] encryptionKey;
byte[] fixedIV;

try
{
    encryptionKey = File.ReadAllBytes(keyPath);
    fixedIV = File.ReadAllBytes(ivPath);
}
catch
{
    encryptionKey = Encoding.UTF8.GetBytes("DefaultKey1234567890123456789012");
    fixedIV = Encoding.UTF8.GetBytes("DefaultIV1234567");
}

app.MapPost("/api/token/validate", async (HttpContext ctx) =>
{
    using var reader = new StreamReader(ctx.Request.Body);
    var encryptedToken = await reader.ReadToEndAsync();

    if (string.IsNullOrEmpty(encryptedToken))
    {
        ctx.Response.StatusCode = 400;
        await ctx.Response.WriteAsync("{\"error\": \"Missing token\"}");
        return;
    }

    try
    {
        byte[] cipherBytes = Convert.FromBase64String(encryptedToken);

        using var aes = Aes.Create();
        aes.Key = encryptionKey;
        aes.IV = fixedIV;
        aes.Mode = CipherMode.CBC;
        aes.Padding = PaddingMode.PKCS7;

        using var decryptor = aes.CreateDecryptor();
        using var msDecrypt = new MemoryStream(cipherBytes);
        using var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read);
        using var srDecrypt = new StreamReader(csDecrypt);

        var plaintext = srDecrypt.ReadToEnd();

        // Validate token structure
        if (!plaintext.StartsWith("TOKEN:") || plaintext.Length < 20)
        {
            ctx.Response.StatusCode = 403;
            await ctx.Response.WriteAsync("{\"error\": \"Invalid token structure\"}");
            return;
        }

        ctx.Response.StatusCode = 200;
        await ctx.Response.WriteAsync("{\"status\": \"valid\", \"subject\": \"" + plaintext.Substring(6, 14) + "\"}");
    }
    catch (CryptographicException)
    {
        // Padding error - distinct from structure validation
        ctx.Response.StatusCode = 400;
        await ctx.Response.WriteAsync("{\"error\": \"Decryption failed\"}");
    }
    catch (FormatException)
    {
        ctx.Response.StatusCode = 400;
        await ctx.Response.WriteAsync("{\"error\": \"Invalid base64 encoding\"}");
    }
});

app.MapGet("/api/token/issue", async (HttpContext ctx) =>
{
    var userId = ctx.Request.Query["user"].ToString();
    if (string.IsNullOrEmpty(userId)) { ctx.Response.StatusCode = 400; return; }

    var tokenPlain = $"TOKEN:{userId.PadRight(14).Substring(0,14)}:{DateTime.UtcNow:yyyyMMddHHmmss}";

    using var aes = Aes.Create();
    aes.Key = encryptionKey;
    aes.IV = fixedIV;
    aes.Mode = CipherMode.CBC;
    aes.Padding = PaddingMode.PKCS7;

    using var encryptor = aes.CreateEncryptor();
    byte[] plainBytes = Encoding.UTF8.GetBytes(tokenPlain);
    byte[] cipherBytes = encryptor.TransformFinalBlock(plainBytes, 0, plainBytes.Length);

    await ctx.Response.WriteAsync(Convert.ToBase64String(cipherBytes));
});

app.Run();
